@import "@fontsource-variable/host-grotesk";
@import "@fontsource-variable/source-code-pro";

/* Light (faithful): the #f6f6f8 page, #111a4a navy ink, #7c7f88-ish grey-blue body text,
   white buttons, #eeeff2 tiles and a #1d2253 navy CTA. Teal-green (#1f8068) highlights the
   stats; cyan (#71d2f0) is the glow of the map art. */
:root {
  --background: oklch(0.974 0.003 286);
  --foreground: oklch(0.244 0.09 270);
  --card: oklch(0.988 0.001 286);
  --card-foreground: oklch(0.244 0.09 270);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.244 0.09 270);
  --primary: oklch(0.279 0.088 275);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(1 0 0);
  --secondary-foreground: oklch(0.244 0.09 270);
  --muted: oklch(0.952 0.004 271);
  --muted-foreground: oklch(0.565 0.025 274);
  --accent: oklch(0.935 0.006 275);
  --accent-foreground: oklch(0.244 0.09 270);
  --destructive: oklch(0.577 0.215 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.919 0.006 275);
  --input: oklch(0.919 0.006 275);
  --ring: oklch(0.457 0.119 270);
  --highlight: oklch(0.539 0.095 172);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.816 0.101 220);
  --chart-1: oklch(0.501 0.174 264);
  --chart-2: oklch(0.614 0.164 138);
  --chart-3: oklch(0.669 0.177 42);
  --chart-4: oklch(0.6 0.17 300);
  --chart-5: oklch(0.532 0.196 11);
  --sidebar: oklch(0.988 0.001 286);
  --sidebar-foreground: oklch(0.244 0.09 270);
  --sidebar-primary: oklch(0.279 0.088 275);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.952 0.004 271);
  --sidebar-accent-foreground: oklch(0.244 0.09 270);
  --sidebar-border: oklch(0.919 0.006 275);
  --sidebar-ring: oklch(0.457 0.119 270);

  --typeface-body: "Host Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Host Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Source Code Pro Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 67rem;
  --page-gutter: 1.25rem;
  --section-y: 7.5rem;
}

/* Dark: the original's teal band. #011821 page, #172c34 panels, white 9% hairlines,
   pale cyan (#88deeb) for keys and the headline, mint (#94efb7) for strings. */
.dark {
  --background: oklch(0.195 0.036 226);
  --foreground: oklch(0.975 0.004 220);
  --card: oklch(0.279 0.031 224);
  --card-foreground: oklch(0.975 0.004 220);
  --popover: oklch(0.275 0.027 234);
  --popover-foreground: oklch(0.975 0.004 220);
  --primary: oklch(0.851 0.085 208);
  --primary-foreground: oklch(0.195 0.036 226);
  --secondary: oklch(0.31 0.03 224);
  --secondary-foreground: oklch(0.975 0.004 220);
  --muted: oklch(0.235 0.034 225);
  --muted-foreground: oklch(0.72 0.017 227);
  --accent: oklch(0.34 0.035 222);
  --accent-foreground: oklch(0.975 0.004 220);
  --destructive: oklch(0.68 0.19 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 9%);
  --input: oklch(1 0 0 / 13%);
  --ring: oklch(0.851 0.085 208);
  --highlight: oklch(0.88 0.118 156);
  --highlight-foreground: oklch(0.195 0.036 226);
  --glow: oklch(0.816 0.101 220);
  --chart-1: oklch(0.72 0.13 258);
  --chart-2: oklch(0.8 0.15 140);
  --chart-3: oklch(0.78 0.13 55);
  --chart-4: oklch(0.74 0.13 296);
  --chart-5: oklch(0.7 0.17 11);
  --sidebar: oklch(0.22 0.035 226);
  --sidebar-foreground: oklch(0.975 0.004 220);
  --sidebar-primary: oklch(0.851 0.085 208);
  --sidebar-primary-foreground: oklch(0.195 0.036 226);
  --sidebar-accent: oklch(0.279 0.031 224);
  --sidebar-accent-foreground: oklch(0.975 0.004 220);
  --sidebar-border: oklch(1 0 0 / 9%);
  --sidebar-ring: oklch(0.851 0.085 208);
}
